import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, {num_points} points are placed in the plane in general position (no three are collinear). Five distinct segments joining pairs of these points are selected uniformly at random from all possible segments. Let the probability that the selected five segments form a connected graph and contain exactly one triangle (i.e., there exist exactly three of the selected segments that form a triangle, and no other cycle occurs) be m/n in lowest terms. Find m+n.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose a number of points ensuring the event is nontrivial and counts are manageable
# We restrict to n in [6, 18] so both attachment patterns are possible and the denominator is large enough.
for _ in range(100):
    n = rng.randint(6, 18)
    # Compute feasibility quickly
    # With n>=6, both T1 and T2 counts are positive.
    if n >= 6:
        return {'num_points': n}
# Fallback (should not happen)
return {'num_points': 6}

    def verifier(assign):
# Recompute the exact probability and return (True, answer) if valid; (False, None) otherwise.
# We enforce nontriviality and correct domain.
import math
# Validate input
if 'num_points' not in assign:
    # Missing slot
    return False, None  # Missing required slot
n = assign['num_points']
if not isinstance(n, int):
    return False, None  # n must be integer
if n < 6:
    return False, None  # Domain too small; problem intended for n>=6
# Helper for combinations
def C(a, b):
    if b < 0 or b > a:
        return 0
    return math.comb(a, b)
# Total edges M in K_n
M = C(n, 2)
# Total 5-edge selections
total = C(M, 5)
# Count of labeled triangles
tri = C(n, 3)
# For a fixed triangle, count valid ways to add two extra edges to make the 5-edge set connected and have exactly one triangle.
# T1: choose two triangle-to-outside pendant edges, avoiding the pattern that creates a second triangle (two different triangle vertices to the same outside vertex).
A = 3 * (n - 3)  # total pendant edges from triangle to outside vertices
T1 = C(A, 2) - 3 * (n - 3)
# T2: choose a path of length 2 attached to some triangle vertex: (p, a) and (a, b) with a, b outside and distinct.
T2 = 3 * (n - 3) * (n - 4)
favorable = tri * (T1 + T2)
# Sanity checks for difficulty: probability must be strictly between 0 and 1.
if favorable <= 0 or favorable >= total:
    return False, None
# Reduce fraction
g = math.gcd(favorable, total)
m = favorable // g
den = total // g
answer = m + den
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

